}
function wrEscapeHtml(value) {
    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/\"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function wrReviewRecords(payload) {
    var reviews = payload && payload.reviews ? payload.reviews : [];
    var records = [];
    var seen = {};
    for (var i = 0; i < reviews.length; i++) {
        var item = reviews[i] || {};
        var wrapper = item;
        var review = item.review && typeof item.review == "object" ? item.review : item;
        if (review.review && typeof review.review == "object") review = review.review;
        var id = String(wrapper.reviewId || review.reviewId || i);
        if (seen[id]) continue;
        seen[id] = true;
        records.push({wrapper: wrapper, review: review});
    }
    return records;
}

function wrParagraphRecords(payload) {
    var groups = payload && payload.reviews ? payload.reviews : [];
    var records = [];
    var seen = {};
    for (var i = 0; i < groups.length; i++) {
        var group = groups[i] || {};
        var pageReviews = group.pageReviews || [];
        var range = String(group.range || "");
        var rangeTotal = Number(group.totalCount || 0);
        for (var j = 0; j < pageReviews.length; j++) {
            var item = pageReviews[j] || {};
            var review = item.review || item;
            var id = String(item.reviewId || review.reviewId || (i + "-" + j));
            if (seen[id]) continue;
            seen[id] = true;
            records.push({wrapper:item, review:review, range:range || String(review.range || ""),
                rangeTotal:rangeTotal, rangeMaxIdx:Number(group.maxIdx || 0),
                rangeHasMore:Boolean(group.hasMore), rangeSynckey:String(group.synckey || "0")});
        }
    }
    return records;
}
function wrLoadReviewReplies(j, src, records, maxReviews) {
    var loadedReviews = 0;
    maxReviews = Number(maxReviews || 5);
    for (var i = 0; i < records.length && loadedReviews < maxReviews; i++) {
        var record = records[i] || {};
        var wrapper = record.wrapper || {};
        var review = record.review || {};
        var reviewId = String(wrapper.reviewId || review.reviewId || "");
        var total = Number(wrapper.commentsCount || review.commentsCount || 0);
        var current = wrapper.hotComments || review.hotComments || [];
        if (!reviewId || total <= current.length) continue;
        var replies = [];
        var seen = {};
        for (var oldIndex = 0; oldIndex < current.length; oldIndex++) {
            var oldReply = current[oldIndex] || {};
            var oldId = String(oldReply.commentId || oldReply.reviewId || oldIndex);
            if (!seen[oldId]) { seen[oldId] = true; replies.push(oldReply); }
        }
        var cursor = 0;
        for (var page = 0; page < 3; page++) {
            try {
                var url = "https://i.weread.qq.com/review/commentloadmore?reviewId=" + encodeURIComponent(reviewId) +
                    "&maxIdx=" + cursor + "&count=100&isExpandAll=0";
                var response = j.get(url, wrHeaderMap(src), 30000);
                if (response.statusCode() != 200) break;
                var data = JSON.parse(String(response.body()));
                var comments = data.comments || [];
                var added = 0;
                for (var replyIndex = 0; replyIndex < comments.length; replyIndex++) {
                    var reply = comments[replyIndex] || {};
                    var id = String(reply.commentId || reply.reviewId || (cursor + replyIndex));
                    if (!seen[id]) { seen[id] = true; replies.push(reply); added++; }
                }
                if (!data.commentsHasMore || !comments.length || !added) break;
                cursor += comments.length;
            } catch (replyError) {
                try { j.log("微信读书回复加载失败：" + replyError); } catch (ignoreReplyLog) {}
                break;
            }
        }
        wrapper.hotComments = replies;
        loadedReviews++;
    }
    return loadedReviews;
}
function wrCommentCards(records, emptyText, sectionIndex) {
    var cards = [];
    var lastRange = "";
    for (var i = 0; i < records.length; i++) {
        var record = records[i] || {};
        var wrapper = record.wrapper || {};
        var review = record.review || {};
        var author = review.author || {};
        var authorName = author.name || author.nick || "微信读书用户";
        var avatarUrl = String(author.avatar || "");
        var avatar = /^https:\/\//i.test(avatarUrl)
            ? "<img class='avatar' loading='lazy' src='" + wrEscapeHtml(avatarUrl) + "' alt=''>"
            : "<span class='avatar avatar-fallback'>" + wrEscapeHtml(String(authorName).charAt(0) || "读") + "</span>";
        var content = review.content || review.htmlContent || review.abstract || review.title || "";
        var context = review.abstract || review.contextAbstract || "";
        var rangeValue = String(record.range || review.range || "");
        var rangeHeading = "";
        if (rangeValue && rangeValue != lastRange) {
            lastRange = rangeValue;
            var rangeTotal = Number(record.rangeTotal || 0);
            rangeHeading = "<div class='range-heading'><div><strong>正文位置 " +
                wrEscapeHtml(rangeValue) + "</strong>" + (rangeTotal > 0 ? "<span>本段共 " + rangeTotal + " 条段评</span>" : "") +
                "</div>" + (context ? "<p>" + wrEscapeHtml(context) + "</p>" : "") + "</div>";
        }
        var created = "";
        if (Number(review.createTime) > 0) {
            var date = new Date(Number(review.createTime) * 1000);
            created = date.getFullYear() + "-" + (date.getMonth() + 1) + "-" + date.getDate();
        }
        var likes = Number(wrapper.likesCount || 0);
        var comments = Number(wrapper.commentsCount || 0);
        var meta = [];
        if (rangeValue) meta.push("位置 " + rangeValue);
        if (review.chapterName || review.chapterTitle) meta.push(String(review.chapterName || review.chapterTitle));
        var badges = [];
        if (review.isAuthorComment) badges.push("作者回复");
        if (review.isAuthorLike) badges.push("作者赞过");
        if (author.isDeepV) badges.push(author.deepVTitle || "资深读者");
        var badgeHtml = [];
        for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
            badgeHtml.push("<span class='badge'>" + wrEscapeHtml(badges[badgeIndex]) + "</span>");
        }
        var scoreHtml = "";
        if (Number(review.star || 0) > 0) {
            var score = Math.round(Number(review.star) / 20 * 10) / 10;
            scoreHtml = "<span class='score'>" + score + " 分</span>";
        }
        var extra = "";
        if (!rangeHeading && context && context != content) extra = "<blockquote>" + wrEscapeHtml(context) + "</blockquote>";
        var pictures = review.pictures || wrapper.pictures || [];
        var pictureHtml = [];
        for (var pictureIndex = 0; pictureIndex < pictures.length; pictureIndex++) {
            var picture = pictures[pictureIndex] || {};
            var pictureUrl = String(picture.url || "");
            if (/^https:\/\//i.test(pictureUrl)) {
                pictureHtml.push("<img class='review-picture' loading='lazy' src='" +
                    wrEscapeHtml(pictureUrl) + "' alt='评论图片'>");
            }
        }
        var replies = wrapper.hotComments || review.hotComments || [];
        var replyHtml = [];
        for (var replyIndex = 0; replyIndex < replies.length; replyIndex++) {
            var reply = replies[replyIndex] || {};
            var replyAuthor = reply.author || {};
            replyHtml.push("<div class='reply'><b>" + wrEscapeHtml(replyAuthor.name || replyAuthor.nick || "回复") + "</b>：" +
                wrEscapeHtml(reply.content || "") + "</div>");
        }
        cards.push("<article class='comment-item" + (i >= 20 ? " batch-hidden" : "") + "'>" + rangeHeading + "<header>" + avatar + "<div class='identity'><div><strong>" + wrEscapeHtml(authorName) +
            "</strong>" + badgeHtml.join("") + "</div><span>" + wrEscapeHtml(created) + "</span></div>" +
            scoreHtml + "</header>" + extra + "<div class='content'>" +
            wrEscapeHtml(content).replace(/\r?\n/g, "<br>") + "</div>" + pictureHtml.join("") + replyHtml.join("") +
            "<footer>" + wrEscapeHtml(meta.join(" · ")) + (meta.length ? "　" : "") +
            "赞 " + likes + "　回复 " + comments + "</footer></article>");
    }
    if (cards.length == 0) cards.push("<div class='empty'>" + wrEscapeHtml(emptyText || "暂时没有可显示的评论") + "</div>");
    return cards.join("");
}
