 }
 function qmC_ParagraphBubbles(bid, cid, cmd5) {
  var marks = {};
  if (!bid || !cid || !cmd5) return marks;
  try {
    var resp = qmC_PostForm.call(this, 'https://api-cmnt.wtzw.com/api/v1/paragraph/bubbles', {
      book_id: String(bid),
      chapters: JSON.stringify([{chapter_id: String(cid), chapter_md5: String(cmd5)}])
    });
    var data = resp && resp.data || {};
    var chapters = data.chapters || [];
    var bubbles = chapters.length ? chapters[0].bubbles || [] : [];
    for (var i = 0; i < bubbles.length; i++) {
      var item = bubbles[i] || {};
      var pid = String(item.p || '');
      if (!pid) continue;
      var count = Number(item.c || 0);
      if (count > 0 || item.gid || item.gtxt) {
        marks[pid] = {count: count, hot: String(item.hot || '') == '1', gid: String(item.gid || ''), gtxt: String(item.gtxt || '')};
      }
    }
  } catch (e) {}
  return marks;
}
function qmC_GodImage(bid, cid, pid, gid, text, paragraphText) {
  text = String(text || '').replace(/[\r\n]+/g, ' ').trim();
  if (!gid || !text) return '';
  if (text.length > 18) text = text.slice(0, 18) + '...';
  var svg = '<svg width="1000" height="120" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="0" width="996" height="100" fill="rgba(255,255,255,0.25)" rx="35" stroke="#444" stroke-width="1"/><rect x="32" y="22" width="140" height="56" rx="20" fill="#000"/><text x="102" y="64" font-size="32" font-family="Arial" fill="#FFF" text-anchor="middle" font-weight="bold">神评</text><text x="196" y="64" font-size="38" font-family="Arial" fill="#111" font-weight="bold">' + qmC_Esc(text) + '</text></svg>';
  var runtimeJava = qmC_JavaOf.call(this);
  if (!runtimeJava || typeof runtimeJava.base64Encode != 'function') return '';
  var encoded = String(runtimeJava.base64Encode(svg)).replace(/[=\r\n]/g, '');
  var call = 'qmC_OpenComment(' + JSON.stringify('paragraph') + ',' + JSON.stringify(String(bid)) + ',' + JSON.stringify(String(cid)) + ',' + JSON.stringify(String(pid)) + ',' + JSON.stringify('七猫神评') + ',' + JSON.stringify(String(paragraphText || '')) + ')';
  return '<img src="data:image/svg+xml;base64,' + encoded + ',' + JSON.stringify({style:'FULL',type:'qmpl-god',click:call}) + '">';
}
function qmC_ChapterPreviewImage(bid, cid) {
  var runtimeJava = qmC_JavaOf.call(this);
  if (!runtimeJava || typeof runtimeJava.base64Encode != 'function') return '';
  var svg = '<svg width="1000" height="120" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="0" width="996" height="100" fill="rgba(255,255,255,0.25)" rx="35" stroke="#444" stroke-width="1"/><rect x="32" y="22" width="150" height="56" rx="20" fill="#000"/><text x="107" y="64" font-size="31" font-family="Arial" fill="#FFF" text-anchor="middle" font-weight="bold">本章说</text><text x="210" y="64" font-size="38" font-family="Arial" fill="#111" font-weight="bold">点击查看本章说</text><text x="935" y="64" font-size="42" font-family="Arial" fill="#111" text-anchor="middle">›</text></svg>';
  var encoded = String(runtimeJava.base64Encode(svg)).replace(/[=\r\n]/g, '');
  var call = 'qmC_OpenComment(' + JSON.stringify('chapter') + ',' + JSON.stringify(String(bid)) + ',' + JSON.stringify(String(cid)) + ',' + JSON.stringify('') + ',' + JSON.stringify('本章说') + ')';
  return '<img src="data:image/svg+xml;base64,' + encoded + ',' + JSON.stringify({style:'FULL',type:'qmpl-chapter-preview',click:call}) + '">';
}
function qmC_AppendComments(text, bid, cid, cmd5) {
  var lines = String(text == null ? '' : text).split('\n');
  var settings = qmC_DisplaySettings.call(this);
  var marks = (settings.paragraph || settings.god) ? qmC_ParagraphBubbles.call(this, bid, cid, cmd5) : {};
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (!line) continue;
    var hash = qmC_Md5.call(this, line);
    if (!hash) continue;
    var pid = hash.slice(0, 8);
    var mark = marks[pid];
    if (!mark) continue;
    if (settings.paragraph && Number(mark.count) > 0) {
      var img = qmC_BubbleSvg.call(this, mark.count, mark.hot, mark.hot ? '热门段评' : '七猫段评');
      var call = 'qmC_OpenComment(' + JSON.stringify('paragraph') + ',' + JSON.stringify(String(bid)) + ',' + JSON.stringify(String(cid)) + ',' + JSON.stringify(String(pid)) + ',' + JSON.stringify('七猫段评') + ',' + JSON.stringify(String(line)) + ')';
      lines[i] += '<img src="' + img + ',' + JSON.stringify({style:'text',type:'qmpl',click:call}) + '">';
    }
    var god = settings.god ? qmC_GodImage.call(this, bid, cid, pid, mark.gid, mark.gtxt, line) : '';
    if (god) lines[i] += '\n' + god;
  }
  if (settings.chapter) {
    var preview = qmC_ChapterPreviewImage.call(this, bid, cid);
    if (preview) lines.push(preview);
  }
  return lines.join('\n');
}

