loginUrl:
let obj = getVariable();
function filterSort(id) {
  obj.sort = id;
  source.setVariable(JSON.stringify(obj));
  java.toast("设置成功");
}
function filterStatus(id) {
  obj.status = id;
  source.setVariable(JSON.stringify(obj));
  java.toast("设置成功");
}
function filterWord(id) {
  obj.word = id;
  source.setVariable(JSON.stringify(obj));
  java.toast("设置成功");
}
function filterDefault() {
  obj = {status: 0, word: 0, sort: 0};
  source.setVariable(JSON.stringify(obj));
  java.toast("设置成功");
}

